fn solid_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
        let Some(pending) = self.solid_pending.as_ref() else {
            return Vec::new();
        };
        if pending.sphere_mode {
            if pending.sphere_kind == "Tangent"
                && pending.sphere_curve.is_empty()
                && pending.points.is_empty()
                && pending.sphere_center.is_none()
            {
                return vec![
                    ("Point", "Point"),
                    ("Undo", "Undo"),
                    ("Cancel", "Cancel"),
                ];
            }
            if matches!(
                pending.sphere_kind,
                "AroundCurve" | "Tangent" | "Tangent2" | "Tangent3"
            ) && !pending.sphere_curve.is_empty()
                && pending.points.is_empty()
                && pending.sphere_center.is_none()
            {
                if matches!(pending.sphere_kind, "Tangent" | "Tangent2") {
                    return vec![
                        ("Point", "Point"),
                        ("Undo", "Undo"),
                        ("Cancel", "Cancel"),
                    ];
                }
                return vec![("Undo", "Undo"), ("Cancel", "Cancel")];
            }
            if pending.points.is_empty() && pending.sphere_center.is_none() {
                return vec![
                    ("Center", "Mode=Center"),
                    ("2Point", "Mode=2Point"),
                    ("3Point", "Mode=3Point"),
                    ("4Point", "Mode=4Point"),
                    ("Vertical", "Mode=Vertical"),
                    ("AroundCurve", "Mode=AroundCurve"),
                    ("FitPoints", "Mode=FitPoints"),
                    ("Tangent", "Mode=Tangent"),
                    ("Cancel", "Cancel"),
                ];
            }
            let mut tokens = Vec::new();
            if (pending.sphere_kind == "TangentPoint" && pending.points.len() >= 2)
                || (pending.sphere_kind == "Tangent" && pending.sphere_center.is_some())
            {
                tokens.push(("Solution=1", "Solution=1"));
                tokens.push(("Solution=2", "Solution=2"));
            }
            tokens.push(("Radius=", "Radius="));
            tokens.push(("Diameter=", "Diameter="));
            tokens.push(("Undo", "Undo"));
            tokens.push(("Cancel", "Cancel"));
            return tokens;
        }
        if !pending.box_mode {
            return Vec::new();
        }
        if pending.points.is_empty() {
            return vec![
                ("Diagonal", "Mode=Diagonal"),
                ("3Point", "Mode=3Point"),
                ("Vertical", "Mode=Vertical"),
                ("Center", "Mode=Center"),
                ("Cube", "Mode=Cube"),
                ("Cancel", "Cancel"),
            ];
        }
        let mut tokens = Vec::new();
        if pending.points.len() == 1 && pending.box_kind == "Diagonal" {
            tokens.push(("Cube", "Mode=Cube"));
        }
        if !pending.points.is_empty() {
            if pending.box_kind == "Center" && pending.points.len() == 1 {
                tokens.push(("Length=", "Length="));
            }
            tokens.push(("Width=", "Width="));
            tokens.push(("Height=", "Height="));
        }
        tokens.push(("Undo", "Undo"));
        tokens.push(("Cancel", "Cancel"));
        tokens
    }

fn circle_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
        let Some(pending) = self.circle_pending.as_ref() else {
            return Vec::new();
        };
        let mut tokens = vec![
            ("Center", "Center"),
            ("2Point", "2Point"),
            ("3Point", "3Point"),
            ("Vertical", "Vertical"),
            ("FitPoints", "FitPoints"),
            ("AroundCurve", "AroundCurve"),
            ("Tangent", "Tangent"),
        ];
        tokens.push(("Deformable", "Deformable"));
        tokens.push(("Approx", "Approx"));
        if pending.deformable {
            tokens.push(("Degree=", "Degree="));
            tokens.push(("PointCount=", "PointCount="));
        }
        if pending.mode == "Tangent" {
            tokens.push(("Radius=", "Radius="));
            tokens.push(("Point=", "Point="));
            tokens.push(("Solution=", "Solution="));
        }
        if pending.points.is_empty() && pending.mode == "AroundCurve" {
            tokens.push(("OnCurve=", "OnCurve="));
        }
        if pending.points.len() == 1 && pending.mode == "Center" {
            tokens.push(("Size=Diameter", "Size=Diameter"));
            tokens.push(("Size=Circumference", "Size=Circumference"));
            tokens.push(("Size=Area", "Size=Area"));
            tokens.push(("Radius=", "Radius="));
            tokens.push(("Diameter=", "Diameter="));
            tokens.push(("Circumference=", "Circumference="));
            tokens.push(("Area=", "Area="));
        }
        if !pending.points.is_empty() {
            tokens.push(("Undo", "Undo"));
        }
        tokens.push(("Cancel", "Cancel"));
        tokens
    }

fn rect_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
        let Some(pending) = self.rect_pending.as_ref() else {
            return Vec::new();
        };
        let mut tokens = vec![
            ("Square", "Square"),
            ("Length=", "Length="),
            ("Cancel", "Cancel"),
        ];
        if pending.points.is_empty() {
            tokens.insert(0, ("Center", "Center"));
            tokens.insert(0, ("3Point", "3Point"));
            tokens.insert(0, ("Vertical", "Vertical"));
        }
        if !pending.points.is_empty() {
            tokens.insert(0, ("Undo", "Undo"));
        }
        tokens
    }

fn interp_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
        let Some(pending) = self.interp_pending.as_ref() else {
            return Vec::new();
        };
        let mut tokens = vec![("Degree=", "Degree=")];
        if pending.points.len() >= 4 {
            tokens.push(("Close", "Close"));
        }
        if !pending.points.is_empty() {
            tokens.push(("Undo", "Undo"));
        }
        tokens.push(("Cancel", "Cancel"));
        tokens
    }

fn ellipse_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
        let Some(pending) = self.ellipse_pending.as_ref() else {
            return Vec::new();
        };
        let mut tokens = Vec::new();
        if pending.points.is_empty() && pending.center.is_none() {
            tokens.extend([
                ("Center", "Center"),
                ("Corner", "Corner"),
                ("Diameter", "Diameter"),
                ("Vertical", "Vertical"),
                ("FromFoci", "FromFoci"),
                ("AroundCurve", "AroundCurve"),
            ]);
        }
        if pending.mode == "AroundCurve" && pending.center.is_none() {
            tokens.push(("OnCurve=", "OnCurve="));
        }
        if pending.mode == "FromFoci" || pending.center.is_some() {
            tokens.push(("MarkFoci", "MarkFoci"));
        }
        tokens.push(("Deformable", "Deformable"));
        tokens.push(("Approx", "Approx"));
        if pending.deformable {
            tokens.push(("Degree=", "Degree="));
            tokens.push(("PointCount=", "PointCount="));
        }
        if pending.center.is_some() {
            tokens.push(("RadiusX=", "RadiusX="));
            tokens.push(("RadiusY=", "RadiusY="));
        }
        if pending.center.is_some() || !pending.points.is_empty() {
            tokens.push(("Undo", "Undo"));
        }
        tokens.push(("Cancel", "Cancel"));
        tokens
    }

fn arc_option_tokens(&self) -> Vec<(&'static str, &'static str)> {
